import {twoLettersSource,lettersView,lettersCards,lettersComparison,lettersHelpExample,createLettersPage,chooseLettersWords,useLettersSupport,keepLettersPage,reviseLettersPage} from './two-letters-core.mjs';
import {hearButton} from './play-media.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const T={unsupported:"This notebook's earlier Two Letters value is retained. New pages cannot be added here. Other places stay open.",unreadable:'This earlier page is retained in your notes. It cannot be changed here. Other pages stay open.',helper:'This earlier example is retained in your notes. The letter choices are still open.',capacity:'There are 24 pages here already. Earlier pages stay open. Download your notes; no page was removed.',safety:'This change could not fit safely in your downloadable notes. Your earlier work stays as it was.',saveFailure:'This page is in this session, but it could not be saved on this device. Download your notes.',saveOff:'Saving is off. This page lasts for this session. Download your notes to keep a copy.',readOnly:'This page is kept. Revise as a new page to make changes.'};
const labels={fits:'Suits this brief',alternative:'A different register',other:'Check this reader, meaning, word form or letter part'};
const flags={help:'Help opened',comparison:'Read both opened',narration:'Narration requested',together:'Working together reported'};
const btn=(action,text,{disabled=false,primary=false,extra=''}={})=>`<button type="button" class="${primary?'primary':'secondary'}" data-tl-action="${action}" data-tl-${action} ${extra}${disabled?' disabled':''}>${esc(text)}</button>`;
let visit=null;
export function resetTwoLettersVisit(){visit=null;}
function session(state,owner){if(!visit||visit.state!==state||visit.owner!==owner)visit={state,owner,id:null,index:0,page:0,review:0,pending:new Map(),peeks:new Map(),helper:null,step:0,toolsOpen:false,notice:''};return visit;}
const key=(s,q)=>`${s.id}/${q.id}`;
const answer=(v,q)=>v.answers.find(a=>a.questionId===q.id);
const option=(v,q)=>q.options.find(o=>o.id===answer(v,q)?.choiceId);
function support(s){return `<ul class="tl-support">${Object.entries(flags).map(([k,l])=>`<li>${l}: ${s[k]?'Yes':'No'}</li>`).join('')}</ul>`;}
function sourceContext(source){return `<section class="tl-source"><p class="tl-source-badge">${esc(source.notice)}</p><details class="tl-news"><summary>Read the news</summary><p><strong>${esc(source.origin)}</strong></p><p>${esc(source.context)}</p></details></section>`;}
function brief(l){return `<div class="tl-brief"><p class="tl-reader ${l.id==='nuria'?'tl-friend':'tl-council'}"><strong>Reader:</strong> ${esc(l.reader)}</p><p><strong>The job:</strong> ${esc(l.purpose)}</p></div>`;}
function letterText(v,l,current=null,before=false){return l.parts.map(p=>{if(Object.hasOwn(p,'text'))return esc(p.text);const q=v.source.questions.find(q=>q.id===p.questionId),o=!before&&option(v,q);return `<span class="tl-gap${current===q.id?' tl-current-gap':''}"${current===q.id?' aria-current="step"':''}>${o?esc(o.text):'Words waiting'}</span>`;}).join('');}
function letter(v,l,current=null,before=false){return `<article class="tl-letter" data-tl-letter="${esc(l.id)}"><h3>${esc(l.title)}</h3>${brief(l)}<div class="tl-letter-text">${letterText(v,l,current,before)}</div></article>`;}
function feedback(v,q,compact=false){const a=answer(v,q),o=option(v,q);return a&&o?`<section class="tl-feedback${compact?' tl-reader-reply':''}" data-tl-feedback><p><strong>Your words: ${esc(o.text)}</strong></p><p><strong>${esc(labels[a.outcome])}</strong></p><p>${esc(o.feedback)}</p>${compact?`<details class="tl-explanation"><summary>Look closer at this choice</summary><p>${esc(q.explanation)}</p>`:''}<p class="tl-outcome">Recorded category: ${esc(a.outcome)}</p><p>Feedback available on revisit: ${a.afterFeedback?'Yes':'No'}</p>${compact?`<h3>Support before this choice</h3>${support(a.supportBefore)}</details>`:''}</section>`:'';}
function summary(v,q){const a=answer(v,q);return `<article class="tl-summary"><h3>${esc(q.prompt)}</h3>${q.line?`<p class="tl-line">${esc(q.line)}</p>`:''}${a?`${feedback(v,q)}<h4>Support before this choice</h4>${support(a.supportBefore)}`:'<p>Words waiting</p>'}${q.guidedSteps.length?'<p>Guided steps supplied</p>':''}</article>`;}
function raw(value){try{return JSON.stringify(value,null,2)??String(value);}catch{return 'Earlier value retained in the notebook.';}}
function rawDetails(value){return `<details class="tl-raw"><summary>Original Two Letters notes, including retained unreadable values</summary><pre>${esc(raw(value))}</pre></details>`;}
function chooser(s,v){const source=twoLettersSource(),max=Math.max(0,Math.ceil(v.sheets.length/6)-1);s.page=Math.min(s.page,max);return `${sourceContext(source)}<section class="tl-chooser"><h2 id="tl-question" tabindex="-1">Shall we try these two letters?</h2><p>Dot has two letters on her counter. Choose some words, then read what you made. You can keep an unfinished page.</p>${btn('start',v.sheets.length?'Start another page with these same letters':'Start a page',{primary:true,disabled:!v.canCreate})}${v.status==='unsupported'?`<p>${T.unsupported}</p>`:!v.canCreate?`<p>${v.sheets.length>=24?T.capacity:'A new page could not be started. Your earlier pages stay as they were.'}</p>`:''}</section>${v.sheets.length?`<section class="tl-history"><h2>Earlier pages</h2><div class="tl-page-list">${v.sheets.slice(s.page*6,s.page*6+6).map(r=>r.readable&&!r.ambiguous?btn('open',`${r.source.title} · ${r.id} · ${r.answers.length} of ${r.source.questions.length} choices made · ${r.kept?'Kept page':'In progress'}`,{extra:`data-tl-id="${esc(r.id)}"`}):'<p>Earlier page retained · its original stays in your notes.</p>').join('')}</div><div class="tl-actions">${btn('pages-previous','Previous pages',{disabled:s.page===0})}<span>Page ${s.page+1} of ${max+1}</span>${btn('pages-next','Next pages',{disabled:s.page===max})}</div></section>`:''}`;}
function narration(v,s){const q=v.source.questions[s.index],l=v.source.letters.find(l=>l.id===q.letterId);const plain=html=>html.replace(/<[^>]*>/g,' ').replace(/&amp;/g,'&').replace(/&lt;/g,'<').replace(/&gt;/g,'>').replace(/&quot;/g,'"').replace(/&#39;/g,"'");if(s.helper==='cards'){const c=lettersCards(v.source)[s.step];return [c.title,c.text,...c.steps].join(' ');}if(s.helper==='help')return s.step===0?q.hint:s.step===1?lettersHelpExample(v.source):'Skip for now. You can come back.';if(s.helper==='compare'){const c=lettersComparison(v.source);return [c.shared,c.differences,...v.source.letters.map(l=>plain(letterText(v,l)))].join(' ');}return [l.reader,l.purpose,q.prompt,q.line,...q.guidedSteps,...q.options.map(o=>o.text),answer(v,q)?`Your words: ${option(v,q).text}. ${labels[answer(v,q).outcome]}. ${option(v,q).feedback}`:''].join(' ');}
function controls(v,s){return `<div class="tl-actions">${hearButton(narration(v,s),'Hear these words').replace('<button','<button data-tl-action="hear" data-tl-hear')}${btn('together',v.support.together?'Working together reported':'Working together')}</div>`;}
function helper(v,s){let body='';if(s.helper==='compare'){const c=lettersComparison(v.source);body=`<h2 id="tl-helper-heading" tabindex="-1">Two readers, two letters</h2><p>${esc(c.shared)}</p><p>${esc(c.differences)}</p><div class="tl-comparison-grid">${v.source.letters.map(l=>`<section class="tl-comparison-letter"><h3>${esc(l.title)}</h3><h4>The supplied letter, with gaps</h4>${letter(v,l,null,true)}<h4>Your chosen words</h4>${letter(v,l)}</section>`).join('')}</div>`;}else if(s.helper==='cards'){const cards=lettersCards(v.source),c=cards[s.step];body=`<h2 id="tl-helper-heading" tabindex="-1">${esc(c.title)}</h2><p>${esc(c.text)}</p><ol>${c.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol><div class="tl-actions">${btn('step-previous','Previous card',{disabled:s.step===0})}<span>Card ${s.step+1} of ${cards.length}</span>${btn('step-next','Next card',{disabled:s.step===cards.length-1})}</div>`;}else{const q=v.source.questions[s.index];body=`<h2 id="tl-helper-heading" tabindex="-1">Try an example</h2><p>${esc(s.step===0?q.hint:s.step===1?lettersHelpExample(v.source):'Skip for now. You can come back.')}</p><div class="tl-actions">${btn('step-previous','Back',{disabled:s.step===0})}${btn('step-next',s.step===0?'Try a greeting example':'Next',{disabled:s.step===2})}${s.step===2?btn('skip','Skip for now'):''}</div>`;}return `<section class="tl-helper">${body}${btn('close','Back to my choice')}${controls(v,s)}</section>`;}
function kept(v,s){const max=Math.max(0,Math.ceil(v.source.questions.length/6)-1);s.review=Math.min(s.review,max);return `<div class="tl-topline">${sourceContext(v.source)}<a class="tl-exit" href="#post">Post Office</a></div><h2 id="tl-question" tabindex="-1">Kept page · ${esc(v.source.title)}</h2><p>${T.readOnly}</p><div class="tl-letters">${v.source.letters.map(l=>letter(v,l)).join('')}</div><h2>Earlier choices</h2>${v.source.questions.slice(s.review*6,s.review*6+6).map(q=>summary(v,q)).join('')}<div class="tl-actions">${btn('review-previous','Previous choices',{disabled:s.review===0})}${btn('review-next','Next choices',{disabled:s.review===max})}</div><h3>Support for this page</h3>${support(v.support)}<div class="tl-actions">${btn('revise','Revise as a new page',{disabled:!v.canRevise,primary:true})}${btn('choose','Choose a page')}<a href="#notes">Grown-up notes</a></div>`;}
function envelopeSwitch(v,s){return `<div class="tl-envelope-switch" role="group" aria-label="Choose a letter">${v.source.letters.map((l,i)=>{const target=v.source.questions.findIndex(q=>q.letterId===l.id);return `<button type="button" class="tl-envelope${v.source.questions[s.index].letterId===l.id?' tl-envelope-current':''}" data-tl-action="letter" data-tl-letter-id="${esc(l.id)}" aria-pressed="${v.source.questions[s.index].letterId===l.id}"${target<0?' disabled':''}><svg viewBox="0 0 120 78" aria-hidden="true" focusable="false"><rect x="5" y="8" width="110" height="64" rx="5" fill="${i%2?'#e5edf7':'#dfeee4'}" stroke="currentColor" stroke-width="2"/><path d="m6 11 54 37 54-37M6 70l38-31m70 31L77 39" fill="none" stroke="currentColor" stroke-width="2"/><circle cx="60" cy="49" r="8" fill="#9b651e"/></svg><span>${esc(l.title)}</span></button>`;}).join('')}</div>`;}
function trial(q,choiceId){const o=q.options.find(o=>o.id===choiceId),word=o?`<span class="tl-pending-word">${esc(o.text)}</span>`:'<span class="tl-pending-word tl-waiting">Words waiting</span>';return q.line.includes('___')?esc(q.line).replace('___',word):`${esc(q.line)}${o?`<span class="tl-selected-line">${word}</span>`:''}`;}
function page(v,s){
 if(!v.readable)return `<h2 id="tl-question" tabindex="-1">Earlier page retained</h2><p>${T.unreadable}</p>${btn('choose','Choose a page')}<a class="tl-exit" href="#post">Post Office</a>`;
 if(v.kept)return kept(v,s);
 if(!v.mutable)return `<h2 id="tl-question" tabindex="-1">Earlier page retained</h2><p>${T.unreadable}</p>${btn('choose','Choose a page')}<a class="tl-exit" href="#post">Post Office</a>`;
 s.index=Math.min(s.index,v.source.questions.length-1);
 if(s.helper){const current=v.source.questions[s.index],l=v.source.letters.find(l=>l.id===current.letterId);return `<div class="tl-stage"><div class="tl-topline">${sourceContext(v.source)}<a class="tl-exit" href="#post">Post Office</a></div>${brief(l)}<details class="tl-helper-source"><summary>Look back at this choice and letter</summary><p>${esc(current.prompt)}</p><p class="tl-line">${esc(current.line)}</p>${letter(v,l,current.id)}</details>${helper(v,s)}</div>`;}
 const q=v.source.questions[s.index],l=v.source.letters.find(l=>l.id===q.letterId),selected=s.pending.has(key(s,q))?s.pending.get(key(s,q)):answer(v,q)?.choiceId;
 return `<div class="tl-stage"><div class="tl-topline">${sourceContext(v.source)}<a class="tl-exit" href="#post">Post Office</a></div>${envelopeSwitch(v,s)}<div class="tl-workspace tl-desk"><div class="tl-source-column">${brief(l)}<details class="tl-letter-disclosure"${s.peeks.get(`${s.id}/${l.id}`)?' open':''}><summary>Peek at the full letter</summary>${letter(v,l,q.id)}</details></div><section class="tl-choice-panel"><h2 id="tl-question" tabindex="-1"><span class="sr-only">${esc(l.reader)} · </span><span class="tl-progress">Choice ${s.index+1} of ${v.source.questions.length}</span></h2>${q.kind==='item'?'<p class="tl-set-a">Your letter is here to look back at, with the words you chose. These short challenges do not change your letter choices.</p>':''}${q.guidedSteps.length?`<div class="tl-guided"><strong>Guided steps supplied</strong><ol>${q.guidedSteps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div>`:''}<p class="tl-preview-label">Try these words</p><p class="tl-line tl-live-line" data-tl-preview aria-live="polite">${trial(q,selected)}</p><fieldset class="tl-word-tiles"><legend>${esc(q.prompt)}</legend>${q.options.map(o=>`<label class="tl-option${selected===o.id?' tl-option-selected':''}"><input type="radio" name="tl-choice" data-tl-choice value="${esc(o.id)}"${selected===o.id?' checked':''}><span>${esc(o.text)}</span></label>`).join('')}</fieldset><p class="tl-selection-note"${selected?' hidden':''}>Choose some words first.</p>${feedback(v,q,true)}</section></div><div class="tl-bottom-bar"><div class="tl-seal-action">${btn('use','Use these words',{primary:true,disabled:!selected})}</div><div class="tl-navigation">${btn('previous','Previous choice',{disabled:s.index===0})}${btn('next','Next choice',{disabled:s.index===v.source.questions.length-1})}</div><details class="tl-tools" data-tl-tools${s.toolsOpen?' open':''}><summary data-tl-tools-toggle>Letter tools</summary><div class="tl-tools-panel"><div class="tl-actions">${btn('keep','Keep this page')}${answer(v,q)?btn('explore','Explore another wording'):''}${lettersComparison(v.source)?btn('compare','Read both'):''}${lettersHelpExample(v.source)?btn('help',"I'm stuck"):''}${lettersCards(v.source)?btn('cards','Read the three teaching cards'):''}</div>${controls(v,s)}${btn('choose','Choose a page')}<a href="#notes">Grown-up notes</a><details class="tl-grown-up"><summary>About these choices</summary>${support(v.support)}<p>Supplied choices show choices for these briefs. They do not show independent writing or how someone speaks. Let the child explain if they want to; do not correct home speech.</p><p>If you like, tell a grown-up another way to ask for a copy. Or write it on paper. These words stay offscreen; nothing is recorded or marked.</p></details>${!lettersComparison(v.source)||!lettersHelpExample(v.source)||!lettersCards(v.source)?`<p>${T.helper}</p>`:''}</div></details></div></div>`;
}
export function twoLettersEntry(){return '<aside class="tl-entry"><h2>Two Letters</h2><p>Choose words for two readers.</p><a class="secondary" href="#post/register">Two Letters</a></aside>';}
export function twoLettersPage(state,owner){const s=session(state,owner),v=lettersView(state,s.id);return `<div class="tl-page" data-tl-root="${s.id?'page':'chooser'}"><header class="tl-header"><h1 id="tl-heading" tabindex="-1">Two Letters</h1>${!s.id||s.helper?'<p>There is more than one good way to speak English. Choose words for this reader and this job.</p>':''}</header><p id="tl-status" class="tl-notice${s.notice?'':' sr-only'}" role="status" aria-live="polite" tabindex="-1">${esc(s.notice)}</p>${s.id?page(v,s):chooser(s,v)}${s.id&&v.mutable?'':'<footer class="tl-actions"><a href="#post">Post Office</a><a href="#post/letters">Change a letter</a><a href="#notes">Grown-up notes</a></footer>'}</div>`;}
export function bindTwoLetters(state,ctx){
 const root=document.querySelector('[data-tl-root]');if(!root)return;const owner=ctx.explorerId(),s=session(state,owner),options={canExport:ctx.canExport};
 const renderedId=s.id,renderedIndex=s.index,renderedHelper=s.helper,rendered=lettersView(state,s.id),renderedQuestion=rendered.source?.questions?.[s.index],choices=renderedQuestion?.options.map(o=>o.id).join('\0');
 const live=()=>root.isConnected&&visit===s&&ctx.notebook()===state&&ctx.explorerId()===owner&&ctx.isActive?.()!==false&&location.hash==='#post/register'&&s.id===renderedId&&s.index===renderedIndex&&s.helper===renderedHelper&&(!renderedQuestion||lettersView(state,s.id).source?.questions?.[s.index]?.id===renderedQuestion.id&&lettersView(state,s.id).source.questions[s.index].options.map(o=>o.id).join('\0')===choices);
 const stop=()=>{ctx.stopSpeech?.();ctx.stopSound?.();};const focus=sel=>ctx.focus?ctx.focus(sel):document.querySelector(sel)?.focus();
 const notify=(text,move=true)=>{if(!live())return;s.notice=text;const n=root.querySelector('#tl-status');if(n){n.textContent=text;n.classList.remove('sr-only');if(move)n.focus();}};
 const refresh=target=>{const peek=root.querySelector('.tl-letter-disclosure');if(peek&&renderedQuestion)s.peeks.set(`${renderedId}/${renderedQuestion.letterId}`,peek.open);ctx.render();if(target)focus(target);};const local=(change,target='#tl-question')=>{if(!live())return;stop();change();refresh(target);};
 const failure=type=>{const v=lettersView(state,s.id);return v.status==='unsupported'?T.unsupported:s.id&&!v.readable?T.unreadable:s.id&&!v.mutable&&type!=='revise'?T.readOnly:(type==='start'||type==='revise')&&!v.canCreate?(v.sheets.length>=24?T.capacity:'A new page could not be started. Your earlier pages stay as they were.'):T.safety;};
 const mutate=(change,{target='#tl-question',message='',type='',after=null,noRender=false}={})=>{if(!live())return false;stop();const before=state.twoLetters,result=change();if(result===false){notify(failure(type));return false;}const changed=state.twoLetters!==before;let saved=null;if(changed)saved=ctx.save?.();if(after)after(result);if(changed){s.notice=saved?.ok===false?T.saveFailure:saved?.enabled===false?(message.startsWith('Page kept.')?'Page kept for this session. Its choices are read-only. '+T.saveOff:T.saveOff):message;if(!noRender)refresh(saved?.ok===false?'#tl-status':target);else if(s.notice)notify(s.notice,false);}else if(after&&!noRender)refresh(target);return true;};
 root.querySelector('.tl-letter-disclosure')?.addEventListener('toggle',e=>{if(live()&&renderedQuestion)s.peeks.set(`${renderedId}/${renderedQuestion.letterId}`,e.currentTarget.open);});
 root.querySelector('[data-tl-tools]')?.addEventListener('toggle',e=>{if(live())s.toolsOpen=e.currentTarget.open;});
 const all=(name,fn)=>root.querySelectorAll(`[data-tl-action="${name}"]`).forEach(b=>b.addEventListener('click',()=>{if(live()&&!b.disabled)fn(b);}));
 const open=id=>{s.id=id;s.helper=null;s.step=0;s.review=0;s.notice='';const v=lettersView(state,id);s.index=v.readable?Math.max(0,v.source.questions.findIndex(q=>!answer(v,q))):0;};
 all('start',()=>mutate(()=>createLettersPage(state,twoLettersSource(),options),{type:'start',after:open}));
 all('open',b=>local(()=>open(b.dataset.tlId)));
 all('choose',()=>local(()=>{s.id=null;s.helper=null;s.notice='';},'#tl-heading'));
 all('pages-previous',()=>local(()=>s.page--,'#tl-question'));all('pages-next',()=>local(()=>s.page++,'#tl-question'));
 all('review-previous',()=>local(()=>s.review--));all('review-next',()=>local(()=>s.review++));
 all('letter',b=>local(()=>{const v=lettersView(state,s.id),index=v.source.questions.findIndex(q=>q.letterId===b.dataset.tlLetterId);if(index>=0)s.index=index;s.notice='';}));
 all('previous',()=>local(()=>{s.index--;s.notice='';}));all('next',()=>local(()=>{s.index++;s.notice='';}));
 root.querySelectorAll('[data-tl-choice]').forEach(r=>r.addEventListener('change',()=>{if(!live()||!r.checked||!renderedQuestion.options.some(o=>o.id===r.value))return;s.pending.set(key(s,renderedQuestion),r.value);root.querySelector('[data-tl-action="use"]').disabled=false;root.querySelector('.tl-selection-note').hidden=true;root.querySelector('[data-tl-preview]').innerHTML=trial(renderedQuestion,r.value);root.querySelectorAll('.tl-option').forEach(label=>label.classList.toggle('tl-option-selected',label.querySelector('input').checked));}));
 all('use',()=>{const q=renderedQuestion,chosen=s.pending.has(key(s,q))?s.pending.get(key(s,q)):answer(lettersView(state,s.id),q)?.choiceId;if(!chosen)return;mutate(()=>chooseLettersWords(state,s.id,q.id,chosen,options));});
 all('explore',()=>{if(!live())return;const group=root.querySelector('fieldset');group?.querySelector('input')?.focus();notify('These same supplied words offer a fitting choice, a different register, or a choice to check for this reader, meaning or letter part.',false);});
 all('keep',()=>mutate(()=>keepLettersPage(state,s.id,options),{target:'#tl-status',message:'Page kept. Its choices are read-only.',after:()=>{s.helper=null;}}));
 all('revise',()=>mutate(()=>reviseLettersPage(state,s.id,options),{type:'revise',after:open}));
 const showHelper=(name,supportKey)=>{s.toolsOpen=true;const before=state.twoLetters;const success=mutate(()=>useLettersSupport(state,s.id,supportKey,options),{noRender:true});if(success){s.helper=name;s.step=0;refresh('#tl-helper-heading');}return before;};
 all('compare',()=>showHelper('compare','comparison'));all('help',()=>showHelper('help','help'));all('cards',()=>showHelper('cards','help'));
 all('step-previous',()=>local(()=>s.step--,'#tl-helper-heading'));all('step-next',()=>local(()=>s.step++,'#tl-helper-heading'));
 all('close',()=>{const trigger=s.helper==='compare'?'compare':s.helper;local(()=>{s.helper=null;s.toolsOpen=true;},`[data-tl-action="${trigger}"]`);});
 all('skip',()=>local(()=>{s.helper=null;s.index=Math.min(s.index+1,lettersView(state,s.id).source.questions.length-1);}));
 all('together',()=>mutate(()=>useLettersSupport(state,s.id,'together',options),{target:'[data-tl-action="together"]',message:'Working together reported'}));
 // Commit support before the existing speech button's native bubble listener.
 // No render here: the connected button must survive to dispatch its request.
 root.addEventListener('click',event=>{const hear=event.target.closest?.('[data-tl-hear]');if(!hear||!root.contains(hear))return;if(!live()||!mutate(()=>useLettersSupport(state,s.id,'narration',options),{noRender:true})){event.preventDefault();event.stopImmediatePropagation();}},{capture:true});
}
export function twoLettersNotes(state){
 if(state===null||typeof state!=='object'||!Object.hasOwn(state,'twoLetters'))return '';
 try{const v=lettersView(state);return `<section class="tl-notes"><h2>Two Letters</h2>${v.status==='unsupported'?`<p>${T.unsupported}</p>`:v.sheets.map((r,i)=>{if(!r.readable||r.ambiguous)return `<p>${T.unreadable}</p>`;const p=lettersView(state,r.id);return `<article><h3>${esc(p.source.title)} · ${esc(r.id)}</h3>${sourceContext(p.source)}<p>${p.kept?'Kept page':'In progress'} · ${p.answers.length} of ${p.source.questions.length} choices made.</p>${v.sheets.slice(0,i).some(earlier=>earlier.readable&&earlier.source.id===p.source.id&&earlier.source.version===p.source.version)?'<p>Same authored letters revisited.</p>':''}${p.source.letters.map(l=>letter(p,l)).join('')}${p.source.questions.map(q=>summary(p,q)).join('')}<h4>Support for this page</h4>${support(p.support)}</article>`;}).join('')||'<p>No pages have been started.</p>'}<p>Supplied choices do not show independent writing or how someone speaks. A No for feedback available does not mean independent, unseen or unaided.</p>${rawDetails(state.twoLetters)}</section>`;}catch{return `<section class="tl-notes"><h2>Two Letters</h2><p>${T.unreadable}</p>${rawDetails(state.twoLetters)}</section>`;}
}
